<template><section class="compliance"><div class="overall"><span>Overall status</span><strong :class="status(values.audit_status).tone">{{ status(values.audit_status).label }}</strong></div><p v-if="!checks.length">No audit results are available yet.</p><div v-for="check in checks" :key="check.key" class="check"><div><h3>{{ check.title }}</h3><p v-if="check.state.tone==='action'">This check needs attention. Open the details or contact the team for guidance.</p></div><div class="check-actions"><span class="badge" :class="check.state.tone">{{ check.state.label }}</span><button v-if="check.state.tone==='action'" type="button" @click="$emit('open',check.target)">View details ›</button></div></div><p class="checked">Last checked: {{ values.audit_date || values.last_audit_date || 'Not available yet' }}</p></section></template>
<script setup>
import {computed} from 'vue'
const props=defineProps({values:{type:Object,required:true}})
defineEmits(['open'])
function status(value){const v=String(value||'').trim().toLowerCase();if(v==='passed')return {label:'Passed',tone:'passed',order:2};if(v==='action required')return {label:'Action needed',tone:'action',order:0};if(v==='pending')return {label:'Under review',tone:'pending',order:1};return {label:value||'Not checked yet',tone:'unknown',order:3}}
const definitions=[['dlm','Driving Licence','Driving Licence'],['pdm','Passport','Identity documents'],['imi','Immigration','Identity documents'],['adm','Address','Address'],['rtw','Right to Work','Identity documents'],['nim','National Insurance','Tax details'],['dbs','Background screening','Background screening'],['bcm','Birth certificate','Identity documents'],['odm','Owner driver','app'],['dvla','DVLA check','Driving Licence'],['dva','DVA check','Driving Licence'],['pob','Proof of bank','app'],['agreements','Agreements','agreements']]
const checks=computed(()=>definitions.map(([suffix,title,target])=>({key:'audit_status_'+suffix,title,target,value:props.values['audit_status_'+suffix]})).filter(c=>c.value&&String(c.value).trim().toLowerCase()!=='not required').map(c=>({...c,state:status(c.value)})).sort((a,b)=>a.state.order-b.state.order))
</script>
<style scoped>
.overall{display:flex;justify-content:space-between;align-items:center;padding:1.2rem;background:#f5f7fa;border-radius:12px;margin:1rem 0;font-size:.9rem}.check{display:flex;justify-content:space-between;gap:1rem;padding:1rem 0;border-bottom:1px solid #e8edf2}.check h3{font-size:.9rem;font-weight:600;margin:0}.check p{font-size:.75rem;color:#687586;max-width:24rem;line-height:1.5}.check-actions{display:flex;flex-direction:column;align-items:flex-end;gap:.5rem;flex-shrink:0}.badge{border-radius:20px;padding:.3rem .65rem;font-size:.7rem;font-weight:600}.passed{color:#166534;background:#edf8ef}.pending{color:#8a5700;background:#fff5d9}.action{color:#b42318;background:#fef0ee}.unknown{color:#5b6776;background:#edf0f4}.overall strong{padding:.4rem .65rem;border-radius:8px}button{background:none;border:0;color:#a61d1d;min-height:36px;font-size:.75rem;cursor:pointer}.checked{color:#758091;font-size:.75rem;margin-top:1.25rem}
</style>
